def arrow(d,x,y,xx,yy,label=None):
    d.add(Line(x,y,xx,yy,strokeColor=colors.black,strokeWidth=.7))
    import math
    a=math.atan2(yy-y,xx-x); s=5
    d.add(Polygon([xx,yy,xx-s*math.cos(a-.45),yy-s*math.sin(a-.45),xx-s*math.cos(a+.45),yy-s*math.sin(a+.45)],fillColor=colors.black))
    if label:d.add(String((x+xx)/2+4,(y+yy)/2+4,label,fontName='Helvetica',fontSize=7))
